import{_ as t,a as i,b as e,c as r,d as l,e as s}from"./chunks/image-20261116063213734.DKm6XmDP.js";import{_ as o,o as p,c as _,a2 as n}from"./chunks/framework.CmPiTyN0.js";const k=JSON.parse('{"title":"战术地图","description":"","frontmatter":{"title":"战术地图","outline":"deep"},"headers":[],"relativePath":"wiki/tactical-map.md","filePath":"wiki/tactical-map.md","lastUpdated":1794811249000}'),m={name:"wiki/tactical-map.md"};function c(d,a,g,h,u,P){return p(),_("div",null,[...a[0]||(a[0]=[n('<p><a href="./../index.html">← 返回 Wiki 首页</a></p><h2 id="_9-战术地图" tabindex="-1">9. 战术地图 <a class="header-anchor" href="#_9-战术地图" aria-label="Permalink to &quot;9. 战术地图&quot;">​</a></h2><p>战术地图显示地形、玩家、载具、导弹和 GPS 目标点，支持缩放、拖动、跟随和快捷标记。右键目标可绑定为 GPS 目标，或将目标位置填入 GPS 面板。</p><h3 id="_9-1-与-gps-制导武器联动" tabindex="-1">9.1 与 GPS 制导武器联动 <a class="header-anchor" href="#_9-1-与-gps-制导武器联动" aria-label="Permalink to &quot;9.1 与 GPS 制导武器联动&quot;">​</a></h3><ul><li><p>在战术地图上选择目标点并装订为 GPS 目标。</p></li><li><p>支持单点和多点标记。</p></li><li><p>多点模式可管理多个目标点；雷达模式可在雷达面板中选择目标。</p></li></ul><p><img src="'+t+'" alt="image-20261116062223016"></p><p><img src="'+i+'" alt="image-20261116062328942"><strong>图9.1/9.2 战术地图联动GPS制导武器</strong></p><h3 id="_9-2-与雷达目标列表联动" tabindex="-1">9.2 与雷达目标列表联动 <a class="header-anchor" href="#_9-2-与雷达目标列表联动" aria-label="Permalink to &quot;9.2 与雷达目标列表联动&quot;">​</a></h3><ul><li>战术地图可打开雷达目标列表，显示距离、高度、速度、NCTR 识别、敌我识别和锁定状态。</li><li>可锁定目标，并对满足锁定条件的当前导弹执行快捷发射。</li><li>雷达目标列表支持隐藏友方目标。</li></ul><p><img src="'+e+'" alt="image-20261116062648996"></p><p><img src="'+r+'" alt="image-20261116062852461"></p><p><strong>图9.3/9.4 战术地图联动雷达面板</strong></p><h3 id="_9-3-炮兵地图与小型炮兵地图" tabindex="-1">9.3 炮兵地图与小型炮兵地图 <a class="header-anchor" href="#_9-3-炮兵地图与小型炮兵地图" aria-label="Permalink to &quot;9.3 炮兵地图与小型炮兵地图&quot;">​</a></h3><ul><li><strong>炮兵地图</strong>：选择目标后计算仰角和落点距离，提供高/低弹道解算，左键开火；适用于 RVP 的炮兵武器。</li><li><strong>小型炮兵地图</strong>：选中炮兵武器时在屏幕角落显示紧凑地图，按当前炮口朝向与俯仰正算落点；左键按常规开火路径射击，但清晰的较低，只适合应急使用。</li></ul><p><img src="'+l+'" alt="image-20261116063139342"></p><p><img src="'+s+'" alt="image-20261116063213734"></p><p><strong>图9.5/9.6 炮兵地图</strong></p><hr>',18)])])}const b=o(m,[["render",c]]);export{k as __pageData,b as default};
